rules.body:
when CLIENT_ACCEPTED {
    if { [IP::addr [IP::client_addr] equals 10.0.0.0/8] } {
        pool /Common/p_v4 member 10.0.0.1%2 80
    } elseif { [class match [IP::client_addr] equals /Common/dg_ip] } {
        node 2001:db8::1 80
    } else {
        pool p_rel
    }
    set rd [getfield [IP::client_addr] "%" 2]
}

devices.configText:
#TMSH-VERSION: 17.1.0
# Q8 probe fixture: one object per address/name form. Synthetic; the forms
# follow F5 documentation and the real 15.1.8.2 sample in
# rust/bigip-report-gen/python/tests/data/device-01.bigip.conf where it has
# them (IPv4 /Common/a.b.c.d:port, `address any`, `mask any`, `*:*`,
# `source 0.0.0.0/0`, numeric ports). IPv6, route-domain and service-name
# spellings are from documentation (unverified on a device).
ltm node /Common/10.0.0.1 {
    address 10.0.0.1
}
ltm node /Common/10.0.0.1%2 {
    address 10.0.0.1%2
}
ltm node /Common/2001:db8::1 {
    address 2001:db8::1
}
ltm node /Common/2001:db8::1%2 {
    address 2001:db8::1%2
}
ltm node /Common/fqdn_node {
    fqdn {
        autopopulate enabled
        name example.com
    }
}
ltm node /T1/node_t1 {
    address 10.1.1.1
}
ltm node /Common/app.app/app_node {
    address 10.0.0.3
}
ltm pool /Common/p_v4 {
    members {
        /Common/10.0.0.1:80 {
            address 10.0.0.1
        }
        /Common/10.0.0.1%2:80 {
            address 10.0.0.1%2
        }
    }
    monitor /Common/http
}
ltm pool /Common/p_v6 {
    members {
        /Common/2001:db8::1.80 {
            address 2001:db8::1
        }
        /Common/2001:db8::1%2.443 {
            address 2001:db8::1%2
        }
    }
    monitor /Common/m_v6
}
ltm pool /Common/p_fqdn {
    members {
        /Common/example.com:443 {
            fqdn {
                autopopulate enabled
                name example.com
            }
        }
    }
}
ltm pool /T1/p_rel {
    members {
        node_t1:80 {
            address 10.1.1.1
        }
    }
}
ltm pool /Common/p_http {
    members {
        /Common/10.0.0.1:http {
            address 10.0.0.1
        }
    }
}
ltm pool /Common/app.app/app_pool {
    members {
        /Common/app.app/app_node:8080 {
            address 10.0.0.3
        }
    }
}
ltm virtual /Common/vs_v4 {
    destination /Common/10.0.0.10:80
    mask 255.255.255.255
    pool /Common/p_v4
    source 0.0.0.0/0
}
ltm virtual /Common/vs_rd {
    destination /Common/10.0.0.10%2:443
    mask 255.255.255.255
    source 0.0.0.0%2/0
}
ltm virtual /Common/vs_v6 {
    destination /Common/2001:db8::10.443
    mask ffff:ffff:ffff:ffff:ffff:ffff:ffff:ffff
    pool /Common/p_v6
    source ::/0
}
ltm virtual /Common/vs_v6rd {
    destination /Common/2001:db8::10%2.80
    mask ffff:ffff:ffff:ffff:ffff:ffff:ffff:ffff
}
ltm virtual /Common/vs_any {
    destination /Common/0.0.0.0:0
    ip-forward
    mask any
    source 0.0.0.0/0
}
ltm virtual /Common/vs_any6 {
    destination /Common/any6.any
    ip-forward
    mask any6
}
ltm virtual /Common/vs_http {
    destination /Common/10.0.0.11:http
    mask 255.255.255.255
}
ltm virtual /Common/vs_net {
    destination /Common/10.0.1.0:0
    mask 255.255.255.0
}
ltm virtual /T1/vs_t1 {
    destination /T1/10.1.1.10:80
    mask 255.255.255.255
    pool p_rel
    rules {
        /Common/r_addr
    }
}
ltm virtual /Common/app.app/app_vs {
    destination /Common/app.app/10.0.0.12:80
    mask 255.255.255.255
    pool /Common/app.app/app_pool
}
ltm virtual /Common/vs_legacy6 {
    destination /Common/fe80::1:80
    mask ffff:ffff:ffff:ffff:ffff:ffff:ffff:ffff
}
ltm virtual-address /Common/10.0.0.10 {
    address 10.0.0.10
    mask 255.255.255.255
}
ltm virtual-address /Common/10.0.0.10%2 {
    address 10.0.0.10%2
    mask 255.255.255.255
}
ltm virtual-address /Common/0.0.0.0 {
    address any
    mask any
}
ltm virtual-address /Common/any6 {
    address any6
    mask any6
}
ltm virtual-address /Common/2001:db8::10 {
    address 2001:db8::10
    mask ffff:ffff:ffff:ffff:ffff:ffff:ffff:ffff
}
ltm snat-translation /Common/10.0.0.50%2 {
    address 10.0.0.50%2
}
ltm snatpool /Common/sp_rd {
    members {
        /Common/10.0.0.50%2
    }
}
ltm monitor http /Common/m_alias {
    defaults-from /Common/http
    destination 10.0.0.1:80
}
ltm monitor http /Common/m_any {
    defaults-from /Common/http
    destination *:*
}
ltm monitor http /Common/m_v6 {
    defaults-from /Common/http
    destination *.*
}
ltm monitor http /Common/m_v6alias {
    defaults-from /Common/http
    destination 2001:db8::1.80
}
ltm data-group internal /Common/dg_ip {
    records {
        10.0.0.0/8 { }
        10.0.0.0%2/8 { }
        2001:db8::/32 { }
        192.168.1.1 { }
    }
    type ip
}
ltm rule /Common/r_addr {
when CLIENT_ACCEPTED {
    if { [IP::addr [IP::client_addr] equals 10.0.0.0/8] } {
        pool /Common/p_v4 member 10.0.0.1%2 80
    } elseif { [class match [IP::client_addr] equals /Common/dg_ip] } {
        node 2001:db8::1 80
    } else {
        pool p_rel
    }
    set rd [getfield [IP::client_addr] "%" 2]
}
}
net self /Common/self_rd {
    address 10.0.0.2%2/24
    vlan /Common/internal
}
net self /Common/self_v6 {
    address 2001:db8::2/64
    vlan /Common/internal
}
net route /Common/r_default {
    gw 10.0.0.254
    network default
}
net route /Common/r_rd {
    gw 10.0.0.254%2
    network default%2
}
net route /Common/r_v6 {
    gw 2001:db8::fe
    network default-inet6
}
net route /Common/r_net {
    gw 10.0.0.254%2
    network 172.16.0.0%2/12
}
gtm server /Common/srv1 {
    addresses {
        10.0.0.20 {
            device-name d1
        }
    }
    datacenter /Common/dc1
    virtual-servers {
        vs1 {
            destination 10.0.0.10:80
        }
        vs6 {
            destination 2001:db8::10.443
        }
        vsrd {
            destination 10.0.0.10%2:443
        }
    }
}
gtm pool a /Common/gp {
    members {
        /Common/srv1:vs1 { }
        /Common/srv1:vs6 { }
    }
}
gtm wideip a /Common/www.example.com {
    pools {
        /Common/gp { }
    }
}
security firewall address-list /Common/al {
    addresses {
        10.0.0.0/8 { }
        10.0.0.1-10.0.0.9 { }
        2001:db8::/32 { }
    }
}
security firewall port-list /Common/pl {
    ports {
        80 { }
        8000-8080 { }
    }
}
